CREATE OR REPLACE FUNCTION public.master_v2_resume(p_session uuid, p_expected_control_version bigint, p_request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid(); v_m public.master_v2_sessions%rowtype; v_cp public.master_v2_mechanical_checkpoints%rowtype; v_event jsonb; v_event_id uuid; v_delta interval; v_result jsonb;
begin
  perform public.master_v2_lock_scope(p_session);
  select * into v_m from public.master_v2_sessions where id=p_session for update;
  if v_m.id is null or v_m.stato<>'sospesa' then perform public.combat_v2_fail('ripresa_non_consentita','Sessione non sospesa.',409,p_request_key,'{}'); end if;
  if v_m.master_user<>v_uid then perform public.combat_v2_fail('master_non_proprietario','Solo il Master corrente può riprendere.',403,p_request_key,'{}'); end if;
  if v_m.control_version<>p_expected_control_version then perform public.combat_v2_fail('versione_controllo_obsoleta','Versione controllo obsoleta.',409,p_request_key,'{}'); end if;
  select * into v_cp from public.master_v2_mechanical_checkpoints where master_session_id=p_session and active for update;
  if v_cp.id is null or v_cp.sha256<>public.combat_v2_sha256(v_cp.payload) then perform public.combat_v2_fail('checkpoint_non_valido','Checkpoint mancante o alterato.',409,p_request_key,'{}'); end if;
  v_event:=public.combat_v2_event_begin(p_session,p_request_key,'master_v2_resume',jsonb_build_object('expected',p_expected_control_version),p_expected_control_version);
  if (v_event->>'replay')::boolean then return v_event->'result'; end if; v_event_id:=(v_event->>'event_id')::uuid;
  v_delta:=clock_timestamp()-v_cp.suspended_at;
  update public.master_v2_mechanical_checkpoints set active=false,resumed_at=clock_timestamp(),pause_delta=v_delta,translation_applied_at=clock_timestamp() where id=v_cp.id and translation_applied_at is null;
  update public.master_v2_sessions set stato=coalesce(stato_pre_sospensione,'in_corso'),stato_pre_sospensione=null,suspended_at=null where id=p_session;
  if v_m.tipo='quest' and mission_internal.runtime_enabled()
     and exists(select 1 from public.mission_run_state where master_session_id=p_session and run_phase='sospesa') then
    perform mission_internal.sync_lifecycle(p_session,p_request_key,v_m.control_version,
      (select control_version from public.mission_run_state where master_session_id=p_session),
      (select stato from public.master_v2_sessions where id=p_session));
  end if;
  update public.combat_v2_sessions set state=coalesce(state_before_suspend,'in_corso'),state_before_suspend=null where master_session_id=p_session and state='sospeso';
  update public.master_v2_participants set engagement_state='attivo' where session_id=p_session and engagement_state='sospeso';
  v_result:=public.combat_v2_envelope(p_request_key,jsonb_build_object('state','in_corso','pause_delta',v_delta::text,'translation_applied_once',true));
  return public.combat_v2_event_complete(v_event_id,v_result);
end $function$

CREATE OR REPLACE FUNCTION public.master_v2_suspend(p_session uuid, p_mode text, p_reason text, p_expected_control_version bigint, p_request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid(); v_m public.master_v2_sessions%rowtype; v_event jsonb; v_event_id uuid; v_cp uuid; v_result jsonb;
begin
  perform public.master_v2_lock_scope(p_session);
  select * into v_m from public.master_v2_sessions where id=p_session for update;
  if v_m.id is null then perform public.combat_v2_fail('sessione_inesistente','Sessione inesistente.',404,p_request_key,'{}'); end if;
  if v_m.master_user<>v_uid and not public.combat_v2_is_admin(v_uid) then perform public.combat_v2_fail('master_non_proprietario','Solo il Master corrente o Admin può sospendere.',403,p_request_key,'{}'); end if;
  if v_m.control_version<>p_expected_control_version then perform public.combat_v2_fail('versione_controllo_obsoleta','Versione controllo obsoleta.',409,p_request_key,'{}'); end if;
  if p_mode not in ('normale','emergenza') then perform public.combat_v2_fail('checkpoint_non_valido','Modalità checkpoint non valida.',422,p_request_key,'{}'); end if;
  if v_m.stato not in ('preparazione','in_corso') then perform public.combat_v2_fail('sessione_non_operativa','Sessione non sospendibile.',409,p_request_key,'{}'); end if;
  if p_mode='normale' and exists(select 1 from public.combat_v2_sessions s join public.combat_v2_rounds r on r.session_id=s.id where s.master_session_id=p_session and r.state<>'narrato') then
    perform public.combat_v2_fail('sospensione_non_a_fine_round','La sospensione normale richiede fine round narrato.',409,p_request_key,'{}'); end if;
  v_event:=public.combat_v2_event_begin(p_session,p_request_key,'master_v2_suspend',jsonb_build_object('mode',p_mode,'reason',p_reason,'expected',p_expected_control_version),p_expected_control_version);
  if (v_event->>'replay')::boolean then return v_event->'result'; end if; v_event_id:=(v_event->>'event_id')::uuid;
  v_cp:=public.master_v2_make_checkpoint(p_session,p_mode,p_reason);
  update public.master_v2_sessions set stato_pre_sospensione=stato,stato='sospesa',suspended_at=clock_timestamp() where id=p_session;
  if v_m.tipo='quest' and mission_internal.runtime_enabled()
     and exists(select 1 from public.mission_run_state where master_session_id=p_session and run_phase in ('preparazione','in_corso')) then
    perform mission_internal.sync_lifecycle(p_session,p_request_key,v_m.control_version,
      (select control_version from public.mission_run_state where master_session_id=p_session),'sospesa');
  end if;
  update public.combat_v2_sessions set state_before_suspend=state,state='sospeso' where master_session_id=p_session and state not in ('chiuso','annullato');
  update public.master_v2_participants set engagement_state='sospeso' where session_id=p_session and engagement_state='attivo';
  v_result:=public.combat_v2_envelope(p_request_key,jsonb_build_object('checkpoint_id',v_cp,'state','sospesa'));
  return public.combat_v2_event_complete(v_event_id,v_result);
end $function$

